# ! [doc = " An immutable, owned value (except for interior mutability)."] # ! [doc = ""] # ! [doc = " The purpose of `Frozen` is to make a value immutable for the sake of defensive programming. For example,"] # ! [doc = " suppose we have the following:"] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " struct Bar { /* some data */ }"] # ! [doc = ""] # ! [doc = " struct Foo {"] # ! [doc = "     /// Some computed data that should never change after construction."] # ! [doc = "     pub computed: Bar,"] # ! [doc = ""] # ! [doc = "     /* some other fields */"] # ! [doc = " }"] # ! [doc = ""] # ! [doc = " impl Bar {"] # ! [doc = "     /// Mutate the `Bar`."] # ! [doc = "     pub fn mutate(&mut self) { }"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " Now suppose we want to pass around a mutable `Foo` instance but, we want to make sure that"] # ! [doc = " `computed` does not change accidentally (e.g. somebody might accidentally call"] # ! [doc = " `foo.computed.mutate()`). This is what `Frozen` is for. We can do the following:"] # ! [doc = ""] # ! [doc = " ```"] # ! [doc = " # struct Bar {}"] # ! [doc = " use rustc_data_structures::frozen::Frozen;"] # ! [doc = ""] # ! [doc = " struct Foo {"] # ! [doc = "     /// Some computed data that should never change after construction."] # ! [doc = "     pub computed: Frozen<Bar>,"] # ! [doc = ""] # ! [doc = "     /* some other fields */"] # ! [doc = " }"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " `Frozen` impls `Deref`, so we can ergonomically call methods on `Bar`, but it doesn't `impl"] # ! [doc = " DerefMut`. Now calling `foo.compute.mutate()` will result in a compile-time error stating that"] # ! [doc = " `mutate` requires a mutable reference but we don't have one."] # ! [doc = ""] # ! [doc = " # Caveats"] # ! [doc = ""] # ! [doc = " - `Frozen` doesn't try to defend against interior mutability (e.g. `Frozen<RefCell<Bar>>`)."] # ! [doc = " - `Frozen` doesn't pin it's contents (e.g. one could still do `foo.computed ="] # ! [doc = "    Frozen::freeze(new_bar)`)."] use split_decls_genesis :: ourprelude :: * ; #[doc = " An owned immutable value."] #[derive (Debug , Clone)] pub struct Frozen < T > (T) ; impl < T > Frozen < T > { pub fn freeze (val : T) -> Self { Frozen (val) } } impl < T > std :: ops :: Deref for Frozen < T > { type Target = T ; fn deref (& self) -> & T { & self . 0 } }